// A rejected lazy chunk reaches this boundary. It reports only that the view
// could not load; it never implies the saved records are empty or changed.
class ReportViewBoundary extends Component<{name:string;children:ReactNode},{failed:boolean}>{
 state={failed:false};
 static getDerivedStateFromError(){return {failed:true}}
 render(){
  if(this.state.failed)return <div className="notice danger" role="alert"><CircleHelp size={16}/><span>The {this.props.name} view could not be loaded. Reload the page to try again.</span><button onClick={()=>window.location.reload()}>Reload page</button></div>;
  return this.props.children;
 }
}
function ReportView({name,children}:{name:string;children:ReactNode}){
 return <ReportViewBoundary key={name} name={name}><Suspense fallback={<div className="loading-state" role="status"><LoaderCircle className="spin" size={22}/><p>Loading {name}…</p></div>}>{children}</Suspense></ReportViewBoundary>;
}

function ChartView({name,hidden,className="chart",children}:{name:string;hidden:boolean;className?:string;children:ReactNode}){
 return <DeferredChart hidden={hidden} name={name} className={className}><ReportViewBoundary name={name}>{children}</ReportViewBoundary></DeferredChart>;
}

const SAVED_DATA_LOAD_ERROR="Saved records could not be loaded.";
async function readSavedDashboard():Promise<Saved>{
 try{
  const response=await fetch("/api/data",{cache:"no-store"});
  if(!response.ok)throw new Error(SAVED_DATA_LOAD_ERROR);
  const value=await response.json() as Partial<Saved>|null;
  if(!value||typeof value!=="object"||Array.isArray(value)||!Object.prototype.hasOwnProperty.call(value,"dataset"))throw new Error(SAVED_DATA_LOAD_ERROR);
  const dataset=value.dataset;
  // Validate the complete renderer contract before a successful read can replace
  // the displayed snapshot. Keep valid legacy source fields without transforming them.
  if(dataset!==null&&!datasetSchema.safeParse(dataset).success)throw new Error(SAVED_DATA_LOAD_ERROR);
  return {dataset:dataset as Dataset|null,overrides:value.overrides||{},settings:value.settings||{},retirementOverrides:value.retirementOverrides||{},reviewPreferences:value.reviewPreferences||{findingResolutions:{},recurringStatuses:{}},refresh:value.refresh||null};
 }catch{throw new Error(SAVED_DATA_LOAD_ERROR)}
}
function DashboardDataState({loading,error,hasDataset,busy,onRetry,onImport}:{loading:boolean;error:string;hasDataset:boolean;busy:boolean;onRetry:()=>void;onImport:(opener:HTMLElement)=>void}){
 if(hasDataset)return error?<div className="notice danger" role="alert"><CircleHelp size={16}/><span>Saved records could not be reloaded. The previously loaded snapshot is still shown.</span><button disabled={busy} onClick={onRetry}>Try again</button></div>:null;
 if(loading)return <div className="loading-state" role="status"><LoaderCircle className="spin" size={25}/><h2>Loading your finances</h2><p>Reading the saved snapshot.</p></div>;
 if(error)return <div className="welcome-panel" role="alert"><CircleHelp size={28} style={{margin:"0 auto 16px"}}/><h2>Saved records could not be loaded</h2><p>Try again to read the saved snapshot. A loading failure does not mean your records are empty.</p><button className="button primary" disabled={busy} onClick={onRetry}><RefreshCw size={16}/>Try again</button></div>;
 return <div className="welcome-panel"><ReportArt kind="records"/><h2>Your workspace is ready for its first import.</h2><p>Import a validated source snapshot, or start with the synthetic local demo described in the README. Your bank credentials stay outside this app.</p><button className="button primary" disabled={!ALLOW_IMPORT} onClick={event=>onImport(event.currentTarget)}><Upload size={16}/>Import dataset</button></div>;
}


