 const changeMonth=(offset:number)=>{const i=monthOptions.indexOf(month);if(monthOptions[i+offset])setMonth(monthOptions[i+offset])};
 const categoryBasisLabel=(transaction:Transaction)=>({user_override:"Your correction",confirmed_context:"Confirmed context",source_semantic:"Source evidence",card_context:"Card context",merchant_identity:"Merchant match",provider:"Provider category",unresolved:"Needs context",income_policy:"Your income rule",user_policy:"Your accounting rule",movement_evidence:"Movement evidence"}[categoryEvidence(transaction).categoryBasis||"provider"]);
 const categoryTitle=(transaction:Transaction)=>categoryEvidence(transaction).categoryReason||`Reported source category: ${transaction.category}`;
 const savedTransactionNote=(t:Transaction)=>saved.overrides[t.id]?.note??saved.dataset?.transactions.find(source=>source.id===t.id)?.note??t.note;
 const editTransaction=(t:Transaction)=>{setEdit(t);setEditFeedback("");setDraft({category:t.category,flow:t.flow,exceptional:t.exceptional,note:savedTransactionNote(t),review:t.review});setReviewChoice(t.reviewDecision||null);setChangingTreatment(false)};
 const editAccount=edit?accountsById.get(edit.accountId):undefined;
 const reviewOptions=edit?eligibleReviewDecisions(edit,editAccount):[];
 const editorState=transactionEditorState(edit,editAccount,draft.note||"",edit?savedTransactionNote(edit):"",reviewChoice,changingTreatment);
 const reviewSuggestion=editorState.suggestion;
 const proposedReview=editorState.proposed;
 const reviewPreview=useMemo(()=>{if(!edit||!proposedReview)return null;try{const candidate={...edit,...(draft.category!==edit.category?{category:draft.category}:{})},resolved=resolveTransactionReview(candidate,editAccount,proposedReview);return resolved?{...candidate,...resolved}:null}catch{return null}},[edit,editAccount,proposedReview,draft.category]);
 const reviewIncomeChange=edit&&reviewPreview?((reviewPreview.flow==="income"&&!reviewPreview.incomePolicyExcluded?-reviewPreview.amount:0)-(edit.flow==="income"&&!edit.incomePolicyExcluded?-edit.amount:0)):0;
 const reviewSpendingChange=edit&&reviewPreview?((reviewPreview.flow==="expense"?reviewPreview.amount:0)-(edit.flow==="expense"?edit.amount:0)):0;
 const reviewEditActive=editorState.active;
 const saveEdit=async(mode:"changes"|"note"|"apply"|"reopen"="changes")=>{
  if(!edit)return;
  setEditFeedback("");
  const changed=changedTransactionPatch(draft,edit,savedTransactionNote(edit));
  let patch:Patch=mode==="note"?{note:draft.note||""}:changed;
  if(mode==="apply"){
   if(!proposedReview||!reviewPreview){tell("Choose a supported treatment before applying your review.");return}
   // The preview uses the derived row; the server validates against the raw
   // source. Carry its accepted category explicitly so both save the same result.
   patch={...changed,category:reviewPreview.category,note:draft.note||"",reviewDecision:proposedReview,review:false};delete patch.flow;
  }else if(mode==="reopen")patch={note:draft.note||"",reviewDecision:null,flow:"review",review:true};
  else if(mode==="changes"&&edit.flow==="review"&&patch.review===false){tell("Choose a treatment and Apply review to resolve this unclassified movement.");return}
  // A direct flow change can make a spending-category draft inactive. Preserve
  // the visible current category, including a category inferred from raw source,
  // rather than persisting the earlier spending draft that is no longer shown.
  if(mode==="changes"&&!["expense","review"].includes(draft.flow??edit.flow)){
   delete patch.category;
   if(draft.flow!==undefined&&draft.flow!==edit.flow)patch.category=edit.category;
  }
  if(!Object.keys(patch).length){tell("No changes to save.");return}
  const finishMutation=savedState.beginMutation();
  setBusy(true);
  try{
   // The write settles (any outcome) before readback; any read overlapping it becomes stale.
   try{const response=await fetch("/api/preferences",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"transaction",id:edit.id,patch})});const result:any=await response.json();if(!response.ok)throw new Error(result.error||"Change could not be saved.");}finally{finishMutation()}
   // Read the saved state back (validated, same ordering policy as Reload) before promising a report or queue change.
   const refreshError="Your change was saved, but the reports could not be refreshed. Reload saved data to check it.";
   const read=savedState.beginRead();
   let outcome:ReadOutcome<Saved>;
   try{outcome=await savedState.readLatest(read,readSavedDashboard)}catch{throw new Error(refreshError)}
   if(outcome.kind!=="commit"||!outcome.value.dataset||!savedState.isCurrentRead(read))throw new Error(refreshError);
   const next=outcome.value;
   const updated=deriveDataset(next.dataset!,next.overrides,next.reviewPreferences).transactions.find(t=>t.id===edit.id);
   setSaved(next);
   setError("");
   if(mode==="apply"&&(!updated||updated.review||updated.flow==="review"||updated.reviewDecision!==proposedReview))throw new Error("Your note was saved, but this transaction still needs a treatment. Reload saved data before trying again.");
   if(mode==="apply"&&updated?.category!==reviewPreview?.category)throw new Error("Your change was saved, but its category differs from the preview. Reload saved data before trying again.");
   if(mode==="note"){
    if(updated)setEdit(updated);
    tell(updated&&(updated.review||updated.flow==="review")?"Note saved. Choose a treatment and Apply review to resolve this transaction.":"Note saved. Its accounting treatment is unchanged.");
   }else if(mode==="reopen"){
    if(updated){setEdit(updated);setDraft({category:updated.category,flow:updated.flow,exceptional:updated.exceptional,note:next.overrides[updated.id]?.note??draft.note,review:updated.review})}
    setReviewChoice("");tell("Returned to review. Choose a new treatment when ready.");
   }else{
    setEdit(null);
    tell(mode==="apply"?`Review applied: ${reviewDecisionLabel(proposedReview)}. Reports and review queues updated.`:updated&&(updated.review||updated.flow==="review")?"Changes saved. This transaction still needs review.":"Changes saved. Reports refreshed from saved data.");
   }
  }catch(error){tell(error instanceof Error?error.message:"Could not save your change.")}finally{finishMutation();setBusy(savedState.isBusy())}
 };
 const saveReviewPreference=(body:{type:"review-resolution";id:string;state:"reviewed"|"open";evidenceKey:string}|{type:"recurring-status";id:string;status:"ongoing"|"stopped"|"detected";effectiveDate:string})=>enqueueReviewPreferenceSave(reviewSaveQueue,async()=>{
  const finishMutation=savedState.beginMutation();
  setBusy(true);
  try{const response=await fetch("/api/preferences",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const result:any=await response.json();if(!response.ok)throw new Error(result.error||"Your review change could not be saved.");if(!result.reviewPreferences)throw new Error("The saved review state was not returned. Reload saved data to check your change.");setSaved(current=>({...current,reviewPreferences:result.reviewPreferences}));tell(body.type==="review-resolution"?(body.state==="reviewed"?"Finding marked reviewed.":"Finding returned to the review queue."):body.status==="detected"?"Service status returned to automatic detection.":`Service marked ${body.status}.`)}
  catch(error){const message=error instanceof Error?error.message:"Your review change could not be saved.";tell(message);throw new Error(message)}finally{finishMutation();setBusy(savedState.isBusy())}
 });
 const resolveFinding=(id:string,state:"reviewed"|"open",evidenceKey:string)=>saveReviewPreference({type:"review-resolution",id,state,evidenceKey});
 const setRecurringStatus=(id:string,status:"ongoing"|"stopped"|"detected",effectiveDate:string)=>saveReviewPreference({type:"recurring-status",id,status,effectiveDate});
 const saveTarget=async()=>{if(CLIENT_READ_ONLY)return;const finishMutation=savedState.beginMutation();setBusy(true);try{const r=await fetch("/api/preferences",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"settings",patch:{savingsTarget:target}})});if(!r.ok)throw new Error("Could not save target.");setSaved(s=>({...s,settings:{...s.settings,savingsTarget:target}}));tell("Savings target saved.");}catch(e){tell(String(e))}finally{finishMutation();setBusy(savedState.isBusy())}};
 const exportBackup=()=>{const payload=backupPayload(saved);if(payload)downloadFile(`neonworth-backup-${payload.dataset.asOf}.json`,JSON.stringify(payload,null,2),"application/json")};
 const exportCsv=()=>{const rows=transactionExportRows(ledger,data?.accounts||[]);downloadFile(`neonworth-transactions-${period?`${period.start}-to-${period.end}`:month}.csv`,serializeCsv(rows),"text/csv")};
 const pickImport=async(e:React.ChangeEvent<HTMLInputElement>)=>{if(!ALLOW_IMPORT){e.target.value="";return;}setImportFeedback("");try{const f=e.target.files?.[0];if(!f)return;if(f.size>8_000_000)throw new Error("Choose a JSON backup smaller than 8 MB.");const obj=JSON.parse(await f.text());const d=obj.dataset||obj;if(d.version!==1||!Array.isArray(d.transactions)||!Array.isArray(d.accounts)||!Array.isArray(d.netWorthHistory))throw new Error("This file is not a Neonworth dataset.");const st=obj.settings;if(st?.savingsTarget!==undefined&&(typeof st.savingsTarget!=="number"||!Number.isFinite(st.savingsTarget)||st.savingsTarget<0||st.savingsTarget>100))throw new Error("The backup has an invalid savings target.");const tags=obj.retirementOverrides;if(tags!==undefined&&(tags===null||typeof tags!=="object"||Array.isArray(tags)))throw new Error("The backup has an invalid retirement classification map.");const review=obj.reviewPreferences;if(review!==undefined&&(review===null||typeof review!=="object"||Array.isArray(review)||!review.findingResolutions||typeof review.findingResolutions!=="object"||Array.isArray(review.findingResolutions)||!review.recurringStatuses||typeof review.recurringStatuses!=="object"||Array.isArray(review.recurringStatuses)))throw new Error("The backup has invalid review preferences.");const corrections=obj.transactionOverrides;if(corrections!==undefined&&(corrections===null||typeof corrections!=="object"||Array.isArray(corrections)||Object.entries(corrections).some(([id,patch])=>!id||id.length>200||["__proto__","constructor","prototype"].includes(id)||patch===null||typeof patch!=="object"||Array.isArray(patch))))throw new Error("The backup has invalid transaction corrections.");setImportTransactionOverrides(corrections===undefined?null:corrections);setImportReviewPreferences(review===undefined?null:review);setImportRetirementOverrides(tags===undefined?null:tags);setImportSettings(st?.savingsTarget!==undefined?{savingsTarget:st.savingsTarget}:null);setConfirmImport(d)}catch(e){tell(e instanceof Error?e.message:"Invalid backup file.")}e.target.value=""};
 const importData=async()=>{
  if(!confirmImport)return;
  const finishMutation=savedState.beginMutation();
  setBusy(true);setImportFeedback("");let applied=false;
  try{
   const r=await fetch("/api/import",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({dataset:confirmImport,...(importRetirementOverrides!==null?{retirementOverrides:importRetirementOverrides}:{}),...(importReviewPreferences!==null?{reviewPreferences:importReviewPreferences}:{}),...(importTransactionOverrides!==null?{transactionOverrides:importTransactionOverrides}:{})})});
   const v:any=await r.json();if(!r.ok)throw new Error(v.error||"Import failed.");
   applied=true;setConfirmImport(null);
   if(importSettings?.savingsTarget!==undefined){
    const prefs=await fetch("/api/preferences",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"settings",patch:importSettings})});
    if(!prefs.ok){finishMutation();await load();throw new Error("Dataset imported, but the savings target could not be restored. Set it again in Cash flow.")}
   }
   setImportSettings(null);setImportRetirementOverrides(null);setImportReviewPreferences(null);setImportTransactionOverrides(null);
   // End the network-write guard before readback: a read must never wait on its own import.
   finishMutation();await load();tell("Dataset and available settings imported.");
  }catch(e){const message=e instanceof Error?e.message:"Import failed.";if(!applied)setImportFeedback(message);tell(message)}
  finally{finishMutation();setBusy(savedState.isBusy())}
 };
