   {!editorState.required&&<button type="button" className="button light" disabled={busy} onClick={()=>{setChangingTreatment(!changingTreatment);setReviewChoice(changingTreatment?edit.reviewDecision||null:null)}}>{changingTreatment?"Keep current treatment":"Change accounting treatment"}</button>}
   {reviewSuggestion&&reviewSuggestion!==edit.reviewDecision&&<p className="review-suggestion"><Sparkles size={14}/><span>Your note suggests <strong>{reviewDecisionLabel(reviewSuggestion)}</strong>. Check the preview, then apply it.</span></p>}
   <TransactionTreatmentSelector active={reviewEditActive} required={editorState.required} proposed={proposedReview} options={reviewOptions} busy={busy} onChange={setReviewChoice}/>
